  rollen_modifikator, begruendung, beleg_programm_url, beleg_studie_url, evidenz, stand, geprueft, ki_entwurf, entwurf_herkunft) values
  (10388, 28, 11, null, 'Elterngeld verbessern und den Partnerschaftsbonus bei vollzeitnaher Teilzeit beider Eltern weiterentwickeln.', '{2801}', null, 1, 3, null, 'Der Partnerschaftsbonus fördert gleichzeitige Teilzeit beider Eltern, wird aber bisher wenig genutzt; ohne Angaben zur Weiterentwicklung ist die Wirkung auf die Aufteilung gering.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=62', null, 'offen', '2026-10-21', false, true, 'blind'),
  (10389, 28, 11, null, 'Steuerliche Absetzbarkeit haushaltsnaher Dienstleistungen verbessern.', '{2801}', null, 1, 3, null, 'Ausgelagerte Hausarbeit erhöht die Erwerbsbeteiligung von Frauen; ein Steuerabzug erreicht aber vor allem höhere Einkommen und weniger Haushalte als direkte Gutscheine.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=15', 'https://www.diw.de/de/diw_01.c.836605.de/das_bisschen_haushalt_____weniger_sorgearbeit_steigert_erwerbsbeteiligung_von_frauen.html', 'gemischt', '2026-10-21', false, true, 'blind'),
  (10390, 28, 11, 'BE', 'Gleichberechtigung als Thema in Kitas und Schulen früh vermitteln', '{2803}', 10384, 1, 3, null, 'Setzt früh an Rollenbildern an und ist mit Lehrplänen und Fortbildung umsetzbar. Ob solche Programme die Erwartungen an Mütter oder die spätere Aufteilung im Haushalt ändern, ist kaum untersucht; Wirkung langfristig und unsicher.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=11', null, 'offen', '2026-10-21', false, true, 'blind'),
  (10391, 28, 11, 'ST', 'Frauen in Technik und Führung gezielt fördern und die Sichtbarkeit weiblicher Vorbilder verbessern', '{2803}', 10386, 1, 3, null, 'Ein Feldexperiment zeigt, dass Besuche weiblicher Vorbilder Stereotype abbauen und MINT-Studienwahl leicht erhöhen. An Erwartungen an Mütter und Familienrollen setzt das nur am Rand an.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=33', 'https://www.iza.org/de/publications/dp/13163', 'belegt', '2026-10-21', false, true, 'blind'),
  (10392, 28, 12, null, 'Elterngeld mit nicht übertragbaren Monaten je Elternteil und weiteren frei verteilbaren Monaten', '{2801}', null, 2, 2, null, 'Sechs nicht übertragbare Monate je Elternteil erhöhen die Väterbeteiligung deutlich (Erfahrungen mit Väterquoten); dauerhafte Effekte auf die Hausarbeit sind schwächer belegt, die Verlängerung kostet viel.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=26', 'https://www.diw.de/de/diw_01.c.836605.de/das_bisschen_haushalt_____weniger_sorgearbeit_steigert_erwerbsbeteiligung_von_frauen.html', 'gemischt', '2026-10-21', false, true, 'blind'),
  (10393, 28, 12, null, 'Freistellung von Vätern oder Partnern nach der Geburt mit Lohnfortzahlung', '{2801}', 10378, 1, 3, null, 'Väterzeit nach der Geburt stärkt frühe Beteiligung und entspricht EU-Vorgaben; Studien finden aber nur bei längeren Freistellungen dauerhafte Effekte, bei Hausarbeit verblassen sie. Umlagefinanzierung per Bundesgesetz machbar.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=26', 'https://childcarecanada.org/node/15425', 'gemischt', '2026-10-21', false, true, 'blind'),
  (10394, 28, 12, null, 'Familienbudget zur Förderung haushaltsnaher Dienstleistungen für Familien', '{2801}', null, 2, 2, null, 'Weniger Hausarbeit erhöht die Erwerbsbeteiligung von Frauen stärker als andere Entlastungen; ein direkt gefördertes Budget erreicht mehr Haushalte als Steuerabzüge. Kosten und Schwarzarbeit sind Hürden.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=26', 'https://www.diw.de/de/diw_01.c.836605.de/das_bisschen_haushalt_____weniger_sorgearbeit_steigert_erwerbsbeteiligung_von_frauen.html', 'belegt', '2026-10-21', false, true, 'blind'),
  (10395, 28, 12, null, 'Steuerliche Reform für Paarfamilien mit dem Ziel, Partnerschaftlichkeit zu fördern', '{2801}', null, 1, 2, null, 'Eine partnerschaftlichere Familienbesteuerung kann Erwerbsanreize für beide stärken; das Ziel bleibt ohne konkretes Modell und schützt bestehende Lebensentscheidungen, die Wirkung ist offen.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=27', null, 'offen', '2026-10-21', false, true, 'blind'),
  (10396, 28, 12, null, 'Steuerliche Begünstigung von Arbeitgeberprämien für Ausweitung der Arbeitszeit von Teilzeitbeschäftigten', '{2802}', null, 1, 3, null, 'Steuerfreie Prämien können Arbeitgeber zur Aufstockung von Teilzeit bewegen; Mitnahmeeffekte sind wahrscheinlich, und Hürden wie Splitting oder Betreuung bleiben.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=24', null, 'offen', '2026-10-21', false, true, 'blind'),
  (10397, 28, 12, null, 'Teilzeitmodelle und Job-Sharing im öffentlichen Dienst als Angebot des Arbeitgebers Staat', '{2802}', 10380, 1, 3, null, 'Mehr Flexibilität kann Vereinbarkeit und höhere Stundenzahl erleichtern. Ohne Rückkehr- oder Aufstockungsrecht bleibt offen, ob Mütter dadurch aus der Teilzeit kommen; längere Tage können Sorgearbeit auch erschweren.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=38', null, 'offen', '2026-10-21', false, true, 'blind'),
  (10398, 28, 12, null, 'Ausbau vollzeitnaher Tätigkeiten in Kitas und Schulen im Rahmen einer Fachkräfteoffensive', '{2802}', null, 1, 1, null, 'Mehr vollzeitnahe Stellen in einem Frauenberuf können ungewollte Teilzeit verringern. Es betrifft nur einen Berufsbereich und hängt von einer Vereinbarung aller Länder und deren Finanzierung ab.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=15', null, 'offen', '2026-10-21', false, true, 'blind'),
  (10399, 28, 12, null, 'Weg aus Mini-Jobs in sozial abgesicherte Arbeit öffnen', '{2802}', null, 1, 3, null, 'Setzt an der Minijob-Teilzeitfalle an, nennt aber kein Instrument; ohne Änderung der Anreize ist nur eine geringe Wirkung zu erwarten.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=14', null, 'offen', '2026-10-21', false, true, 'blind'),
  (10400, 28, 12, null, 'Antidiskriminierungsstelle des Bundes und Beratungsangebote für Betroffene stärken', '{2804}', 10383, 1, 3, null, 'Mehr Beratung erleichtert Betroffenen von Belästigung den Weg zu Hilfe und macht Rechte bekannter. Betriebliche Beschwerdestellen und Pflichten der Arbeitgeber ändert das nicht direkt; Wirkung kaum untersucht.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=41', null, 'offen', '2026-10-21', false, true, 'blind'),
  (10401, 28, 12, null, 'Allgemeines Gleichbehandlungsgesetz modernisieren, um wirksameren Schutz vor Diskriminierung zu bieten', '{2804}', null, 1, 3, null, 'Eine AGG-Reform kann den Schutz vor Belästigung am Arbeitsplatz verbessern; ohne Angaben zu Fristen, Klagerechten oder Beschwerdestellen ist die Wirkung unbestimmt.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=41', null, 'offen', '2026-10-21', false, true, 'blind'),
  (10402, 28, 12, 'ST', 'Präventive und demokratiepädagogische Projekte gegen sexistische Haltungen an Schulen intensivieren und dauerhaft fördern', '{2803}', 10384, 1, 3, null, 'Setzt früh an Rollenbildern an und ist mit Lehrplänen und Fortbildung umsetzbar. Ob solche Programme die Erwartungen an Mütter oder die spätere Aufteilung im Haushalt ändern, ist kaum untersucht; Wirkung langfristig und unsicher.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=36', null, 'offen', '2026-10-21', false, true, 'blind'),
  (10403, 28, 13, null, 'Familienstartzeit: zwei Wochen Freistellung mit Lohnersatz für Väter und Co-Mütter nach der Geburt', '{2801}', 10378, 1, 3, null, 'Väterzeit nach der Geburt stärkt frühe Beteiligung und entspricht EU-Vorgaben; Studien finden aber nur bei längeren Freistellungen dauerhafte Effekte, bei Hausarbeit verblassen sie. Umlagefinanzierung per Bundesgesetz machbar.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=82', 'https://childcarecanada.org/node/15425', 'gemischt', '2026-10-21', false, true, 'blind'),
  (10404, 28, 13, null, 'Elterngeld: Mindest- und Höchstbetrag anheben, Ersatzrate für geringe Einkommen erhöhen', '{2801}', 10377, 1, 2, null, 'Geld ist ein Hauptgrund für kurze Elternzeit der Väter, ein höherer Höchstbetrag senkt diese Hürde etwas. Der Mindestbetrag geht aber vor allem an Mütter ohne Vorerwerb und ändert die Aufteilung kaum; Mehrkosten im Haushalt.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=82', 'https://www.diw.de/de/diw_01.c.673478.de/elterngeld_und_elterngeld_plus_gleichmaessige_aufteilung_zwischen_muettern_und_vaetern_nach_wie_vor_in_weiter_ferne.html', 'gemischt', '2026-10-21', false, true, 'blind'),
  (10405, 28, 13, null, 'Mehr Zeitsouveränität und flexible Arbeitszeitmodelle für die Aufteilung von Care-Arbeit', '{2801}', 10380, 1, 3, null, 'Mehr Flexibilität kann Vereinbarkeit und höhere Stundenzahl erleichtern. Ohne Rückkehr- oder Aufstockungsrecht bleibt offen, ob Mütter dadurch aus der Teilzeit kommen; längere Tage können Sorgearbeit auch erschweren.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=20', null, 'offen', '2026-10-21', false, true, 'blind'),
  (10406, 28, 13, null, 'Brückenteilzeit und Rückkehrrecht in Vollzeit ausweiten und flexibler gestalten', '{2802}', 10379, 2, 2, null, 'Setzt direkt an der ungewollten Dauer-Teilzeit nach der Familienphase an; die bisherige Brückenteilzeit gilt nur in größeren Betrieben. Wirkung kaum evaluiert, Widerstand der Arbeitgeber und Ausnahmen für Kleinbetriebe absehbar.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=69', null, 'offen', '2026-10-21', false, true, 'blind'),
  (10407, 28, 13, null, 'Minijobs schrittweise in sozialversicherungspflichtige Beschäftigung überführen', '{2802}', null, 2, 2, null, 'Minijobs wirken kaum als Brücke und gelten zusammen mit dem Splitting als Teilzeitfalle für Frauen; die Überführung setzt dort an. Kurzfristig drohen Stellenverluste in Branchen mit vielen Minijobs.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=69', 'https://www.boeckler.de/de/auf-einen-blick-17945-minijobs-als-teil-des-niedriglohnsektors-36566.htm', 'gemischt', '2026-10-21', false, true, 'blind'),
  (10408, 28, 13, null, 'Mehr Einfluss der Beschäftigten, vor allem Frauen, auf Lage und Dauer der Arbeitszeit', '{2802}', null, 1, 2, null, 'Mehr Einfluss auf Lage und Dauer der Arbeitszeit kann Wechsel aus der Teilzeit erleichtern; ohne konkrete Rechtsansprüche bleibt die Wirkung unbestimmt.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=68', null, 'offen', '2026-10-21', false, true, 'blind'),
  (10409, 28, 13, null, 'Ehegattensplitting durch individuelle Besteuerung mit übertragbarem Grundfreibetrag für Neuehen ersetzen', '{2802}', 10381, 2, 2, null, 'Das Splitting gilt als Erwerbshemmnis für Zweitverdienerinnen. Simulationen zeigen deutliche Effekte vor allem bei reiner Individualbesteuerung, mit übertragbarem Grundfreibetrag fallen sie kleiner aus; Übergang und Vertrauensschutz aufwendig.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=20', 'https://www.diw.de/de/diw_01.c.763052.de/s_6900.html', 'gemischt', '2026-10-21', false, true, 'blind'),
  (10410, 28, 13, null, 'Feministische Mädchen- und Jungenarbeit besonders fördern', '{2803}', 10387, 1, 2, null, 'Kann Rollenbilder früh hinterfragen; der Bund kann über Förderprogramme beitragen, Schule und Kita regeln aber die Länder. Wirkung auf spätere Rollenteilung kaum untersucht.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=84', null, 'offen', '2026-10-21', false, true, 'blind'),
  (10411, 28, 13, null, 'Allgemeines Gleichbehandlungsgesetz mit längeren Fristen, Verbandsklage und Schließung von Schutzlücken reformieren', '{2804}', null, 2, 3, null, 'Längere Fristen und Verbandsklage erleichtern die Durchsetzung auch bei sexueller Belästigung, die Evaluation des AGG sah hier Bedarf. Betriebliche Beschwerdestellen bekannter macht es nicht direkt.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=116', null, 'offen', '2026-10-21', false, true, 'blind'),
  (10412, 28, 13, null, 'Beratungsstellen gegen Diskriminierung langfristig absichern und ausbauen', '{2804}', 10383, 1, 3, null, 'Mehr Beratung erleichtert Betroffenen von Belästigung den Weg zu Hilfe und macht Rechte bekannter. Betriebliche Beschwerdestellen und Pflichten der Arbeitgeber ändert das nicht direkt; Wirkung kaum untersucht.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=116', null, 'offen', '2026-10-21', false, true, 'blind'),
  (10413, 28, 13, 'BE', 'Klischeefreie Berufsorientierung wird verbindlicher Standard an allen Schulformen.', '{2803}', 10385, 1, 3, null, 'Kann Berufswahl und Rollenbilder etwas öffnen und ist schulrechtlich leicht umsetzbar. Die Erwartungen an Mütter in der Familienphase berührt sie nur am Rand; belastbare Wirkungsstudien fehlen.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=196', null, 'offen', '2026-10-21', false, true, 'blind'),
  (10414, 28, 13, 'MV', 'Mädchen früh für MINT-Fächer begeistern und durch landesweite Kampagnen sichtbare Vorbilder schaffen', '{2803}', 10386, 1, 3, null, 'Ein Feldexperiment zeigt, dass Besuche weiblicher Vorbilder Stereotype abbauen und MINT-Studienwahl leicht erhöhen. An Erwartungen an Mütter und Familienrollen setzt das nur am Rand an.', 'https://gruene-mv.de/?wpdmdl=33772#page=85', 'https://www.iza.org/de/publications/dp/13163', 'belegt', '2026-10-21', false, true, 'blind'),
  (10415, 28, 13, 'ST', 'Schulungen in Kitas, um geschlechterneutrale Erziehung zu fördern und stereotype Rollenbilder abzubauen', '{2803}', 10384, 1, 3, null, 'Setzt früh an Rollenbildern an und ist mit Lehrplänen und Fortbildung umsetzbar. Ob solche Programme die Erwartungen an Mütter oder die spätere Aufteilung im Haushalt ändern, ist kaum untersucht; Wirkung langfristig und unsicher.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=58', null, 'offen', '2026-10-21', false, true, 'blind'),
  (10416, 28, 14, null, 'Volles Elterngeld (14 Monate), wenn beide Elternteile je mindestens vier Elterngeldmonate nehmen.', '{2801}', null, 2, 3, null, 'Mehr reservierte Partnermonate erhöhen die Väterbeteiligung (Quebec, Norwegen) und werden zur Entlastung von Frauen empfohlen; dauerhafte Effekte auf die Hausarbeit sind schwächer belegt.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=30', 'https://www.diw.de/de/diw_01.c.836605.de/das_bisschen_haushalt_____weniger_sorgearbeit_steigert_erwerbsbeteiligung_von_frauen.html', 'gemischt', '2026-10-21', false, true, 'blind'),
  (10417, 28, 14, null, 'Steuerliche Absetzbarkeit von Betreuungskosten und Unterhalt verbessern, um Familien und Alleinerziehende zu entlasten.', '{2801}', null, 1, 3, null, 'Senkt die Kosten ausgelagerter Betreuung etwas und entlastet Familien; steuerliche Abzüge nützen vor allem höheren Einkommen und ändern die Aufteilung im Paar kaum.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=14', null, 'offen', '2026-10-21', false, true, 'blind'),
  (10418, 28, 14, null, 'Arbeitszeitgesetz reformieren: wöchentliche statt tägliche Höchstarbeitszeit, flexible Arbeitszeitmodelle.', '{2802}', 10380, 1, 3, null, 'Mehr Flexibilität kann Vereinbarkeit und höhere Stundenzahl erleichtern. Ohne Rückkehr- oder Aufstockungsrecht bleibt offen, ob Mütter dadurch aus der Teilzeit kommen; längere Tage können Sorgearbeit auch erschweren.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=18', null, 'offen', '2026-10-21', false, true, 'blind'),
  (10419, 28, 14, null, 'Abschaffung der Steuerklassen 3 und 5, um die ökonomische Freiheit von Frauen zu stärken.', '{2802}', null, 1, 3, null, 'Ohne Steuerklasse 5 wirkt das Nettoeinkommen der Zweitverdienerin weniger gering; die Jahressteuer bleibt aber gleich, daher sind nur kleine Effekte auf die Arbeitszeit zu erwarten.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=30', null, 'offen', '2026-10-21', false, true, 'blind'),
  (10420, 28, 14, null, 'Mädchen in der Schule für MINT-Fächer begeistern, um den Anteil von Gründerinnen zu erhöhen.', '{2803}', null, 1, 1, null, 'Vorbilder und MINT-Angebote können Stereotype etwas abbauen (Feldexperiment). Schulunterricht ist aber Ländersache, und an Erwartungen an Mütter setzt das nur am Rand an.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=30', 'https://www.iza.org/de/publications/dp/13163', 'belegt', '2026-10-21', false, true, 'blind'),
  (10421, 28, 14, 'BE', 'Gezielte Ausbildungsbotschafter in Schulen und mehr Praktika, damit Mädchen und Frauen MINT-Berufe offen stehen', '{2803}', 10386, 1, 3, null, 'Ein Feldexperiment zeigt, dass Besuche weiblicher Vorbilder Stereotype abbauen und MINT-Studienwahl leicht erhöhen. An Erwartungen an Mütter und Familienrollen setzt das nur am Rand an.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=81', 'https://www.iza.org/de/publications/dp/13163', 'belegt', '2026-10-21', false, true, 'blind'),
  (10422, 28, 14, 'BE', 'Schwerpunkt auf die Integration von Frauen in Arbeit, unter anderem um tradierte Rollenbilder zu überwinden', '{2803}', null, 1, 2, null, 'Erwerbsintegration von Frauen kann Abhängigkeit und tradierte Rollen verringern. Die Zusage bleibt aber ohne konkretes Instrument, die Wirkung hängt ganz von der Ausgestaltung ab.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=98', null, 'offen', '2026-10-21', false, true, 'blind'),
  (10423, 28, 15, null, 'Betreuungsgehalt bis zum dritten Geburtstag, damit Eltern zwischen Fremd- und Selbstbetreuung wählen können', '{2803}', 10382, 0, 1, null, 'Erweitert die Wahl, senkt laut Studien aber die Erwerbsbeteiligung von Müttern und verfestigt damit Teilzeit und Rollenteilung. Das Bundesverfassungsgericht hat das Bundes-Betreuungsgeld 2015 mangels Bundeszuständigkeit gekippt.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=148', 'https://www.wirtschaftsdienst.eu/inhalt/jahr/2023/heft/5/beitrag/betreuungsgeld-familienpolitische-leistung-oder-hindernis-bei-der-arbeitsmarktintegration.html', 'belegt', '2026-10-21', false, true, 'blind'),
  (10424, 28, 15, null, 'Erziehungsgeld, das Eigenbetreuung der Kinder in den ersten drei Lebensjahren finanziell erleichtert', '{2802}', 10382, 0, 1, null, 'Erweitert die Wahl, senkt laut Studien aber die Erwerbsbeteiligung von Müttern und verfestigt damit Teilzeit und Rollenteilung. Das Bundesverfassungsgericht hat das Bundes-Betreuungsgeld 2015 mangels Bundeszuständigkeit gekippt.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=21', 'https://www.wirtschaftsdienst.eu/inhalt/jahr/2023/heft/5/beitrag/betreuungsgeld-familienpolitische-leistung-oder-hindernis-bei-der-arbeitsmarktintegration.html', 'belegt', '2026-10-21', false, true, 'blind'),
  (10425, 28, 15, null, 'Hilfen beim beruflichen Wiedereinstieg nach der Kinderbetreuung', '{2802}', null, 1, 3, null, 'Hilfen zum Wiedereinstieg setzen an der Familienphase an; ohne Angaben zu Art und Umfang ist nur eine geringe Wirkung zu erwarten.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=21', null, 'offen', '2026-10-21', false, true, 'blind'),
  (10426, 28, 15, 'BE', 'Landeserziehungsgeld für U3-Kinder in Höhe der Kita-Kosten, um die Wahl zwischen häuslicher und externer Betreuung zu stärken', '{2803}', null, 0, 1, null, 'Erweitert die Wahl, Studien zum Betreuungsgeld zeigen aber eine sinkende Erwerbsbeteiligung von Müttern und damit verfestigte Rollen. Ein Betrag in Höhe der Kita-Kosten ist für ein Land kaum finanzierbar.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=59', 'https://www.wirtschaftsdienst.eu/inhalt/jahr/2023/heft/5/beitrag/betreuungsgeld-familienpolitische-leistung-oder-hindernis-bei-der-arbeitsmarktintegration.html', 'belegt', '2026-10-21', false, true, 'blind'),
  (10427, 28, 15, 'ST', 'Girls- und Boys-Day durch einen Zukunftstag zur Berufsorientierung ohne Trennung nach Geschlecht ersetzen.', '{2803}', 10385, 1, 3, null, 'Kann Berufswahl und Rollenbilder etwas öffnen und ist schulrechtlich leicht umsetzbar. Die Erwartungen an Mütter in der Familienphase berührt sie nur am Rand; belastbare Wirkungsstudien fehlen.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=63', null, 'offen', '2026-10-21', false, true, 'blind'),
  (10428, 28, 16, null, 'Für den zweiten Elternteil 28 Tage Elternschutz nach der Geburt einführen, um die partnerschaftliche Aufteilung von Sorge- und Erwerbsarbeit zu fördern.', '{2801}', 10378, 1, 3, null, 'Väterzeit nach der Geburt stärkt frühe Beteiligung und entspricht EU-Vorgaben; Studien finden aber nur bei längeren Freistellungen dauerhafte Effekte, bei Hausarbeit verblassen sie. Umlagefinanzierung per Bundesgesetz machbar.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=16', 'https://childcarecanada.org/node/15425', 'gemischt', '2026-10-21', false, true, 'blind'),
  (10429, 28, 16, null, 'Leerstehende Gewerbeflächen in kommunale oder genossenschaftliche Hand überführen und zu Sorgezentren umgestalten, die pflegende Angehörige unterstützen.', '{2801}', null, 1, 1, null, 'Wohnortnahe Sorgezentren könnten pflegende Angehörige entlasten. Die Überführung privater Gewerbeflächen ist rechtlich und finanziell schwierig, die Wirkung auf die Aufteilung im Paar unklar.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=45', null, 'offen', '2026-10-21', false, true, 'blind'),
  (10430, 28, 16, null, 'Mindestbetrag beim Elterngeld auf 420 Euro anheben.', '{2801}', 10377, 1, 2, null, 'Geld ist ein Hauptgrund für kurze Elternzeit der Väter, ein höherer Höchstbetrag senkt diese Hürde etwas. Der Mindestbetrag geht aber vor allem an Mütter ohne Vorerwerb und ändert die Aufteilung kaum; Mehrkosten im Haushalt.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=16', 'https://www.diw.de/de/diw_01.c.673478.de/elterngeld_und_elterngeld_plus_gleichmaessige_aufteilung_zwischen_muettern_und_vaetern_nach_wie_vor_in_weiter_ferne.html', 'gemischt', '2026-10-21', false, true, 'blind'),
  (10431, 28, 16, null, 'Rechtsanspruch auf eine Vollzeitstelle einführen, auch für familienfreundliche Schichten.', '{2802}', 10379, 2, 2, null, 'Setzt direkt an der ungewollten Dauer-Teilzeit nach der Familienphase an; die bisherige Brückenteilzeit gilt nur in größeren Betrieben. Wirkung kaum evaluiert, Widerstand der Arbeitgeber und Ausnahmen für Kleinbetriebe absehbar.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=27', null, 'offen', '2026-10-21', false, true, 'blind'),
  (10432, 28, 16, null, 'Recht auf vorübergehende Verkürzung der Arbeitszeit für alle Beschäftigte (Teilzeit nach Wunsch).', '{2802}', 10379, 2, 2, null, 'Setzt direkt an der ungewollten Dauer-Teilzeit nach der Familienphase an; die bisherige Brückenteilzeit gilt nur in größeren Betrieben. Wirkung kaum evaluiert, Widerstand der Arbeitgeber und Ausnahmen für Kleinbetriebe absehbar.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=27', null, 'offen', '2026-10-21', false, true, 'blind'),
  (10433, 28, 16, null, 'Ausdrückliches Rückkehrrecht auf den gleichen oder einen gleichwertigen Arbeitsplatz nach der Elternzeit.', '{2802}', null, 1, 3, null, 'Ein ausdrückliches Rückkehrrecht auf einen gleichwertigen Platz sichert den Wiedereinstieg nach der Elternzeit; die Rückkehr ist arbeitsrechtlich schon weitgehend geschützt, der Zugewinn ist klein.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=16', null, 'offen', '2026-10-21', false, true, 'blind'),
  (10434, 28, 16, null, 'Arbeitszeitmodelle mit geringerer Wochenarbeitszeit (z. B. 32 Stunden oder Vier-Tage-Woche) bei vollem Lohn fördern.', '{2802}', null, 1, 1, null, 'Kürzere Normalarbeitszeit könnte die Lücke zwischen Teil- und Vollzeit verkleinern; Pilotstudien zeigen Zufriedenheit, Effekte auf Mütterteilzeit sind unbelegt. Voller Lohnausgleich ist staatlich kaum durchsetzbar.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=16', null, 'offen', '2026-10-21', false, true, 'blind'),
  (10435, 28, 16, null, 'Ehegattensplitting durch eine Individualbesteuerung ersetzen; so sollen alte Geschlechterrollen in der Steuerpolitik entgegengewirkt werden.', '{2803}', 10381, 2, 2, null, 'Das Splitting gilt als Erwerbshemmnis für Zweitverdienerinnen. Simulationen zeigen deutliche Effekte vor allem bei reiner Individualbesteuerung, mit übertragbarem Grundfreibetrag fallen sie kleiner aus; Übergang und Vertrauensschutz aufwendig.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=46', 'https://www.diw.de/de/diw_01.c.763052.de/s_6900.html', 'gemischt', '2026-10-21', false, true, 'blind'),
  (10436, 28, 16, null, 'Geschlechterungleichgewichte auf dem Ausbildungs- und Arbeitsmarkt durch geschlechtersensible Bildung überwinden.', '{2803}', 10387, 1, 2, null, 'Kann Rollenbilder früh hinterfragen; der Bund kann über Förderprogramme beitragen, Schule und Kita regeln aber die Länder. Wirkung auf spätere Rollenteilung kaum untersucht.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=40', null, 'offen', '2026-10-21', false, true, 'blind'),
  (10437, 28, 16, null, 'Arbeitsschutzgesetz um die Aspekte Gewalt und sexuelle Belästigung ergänzen, damit das Gesetz zu Gewalt und Belästigung in der Arbeitswelt in Betrieben ankommt.', '{2804}', null, 2, 3, null, 'Verankert Schutz vor sexueller Belästigung in der Gefährdungsbeurteilung und macht Prävention zur Arbeitgeberpflicht, wie es die ILO-Konvention 190 vorsieht. Wirkung hängt von Kontrolle durch Aufsichtsbehörden ab.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=47', null, 'offen', '2026-10-21', false, true, 'blind'),
  (10438, 28, 16, 'BE', 'Aufklärung und Weiterbildung vor allem in Schulen über Sexismus, häusliche Gewalt und stereotype Rollenbilder', '{2803}', 10384, 1, 3, null, 'Setzt früh an Rollenbildern an und ist mit Lehrplänen und Fortbildung umsetzbar. Ob solche Programme die Erwartungen an Mütter oder die spätere Aufteilung im Haushalt ändern, ist kaum untersucht; Wirkung langfristig und unsicher.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=214', null, 'offen', '2026-10-21', false, true, 'blind'),
  (10439, 28, 16, 'MV', 'Berufsorientierung ohne Geschlechterstereotype; Girls'' Day und Boys'' Day in der 9. Klasse verpflichtend', '{2803}', 10385, 1, 3, null, 'Kann Berufswahl und Rollenbilder etwas öffnen und ist schulrechtlich leicht umsetzbar. Die Erwartungen an Mütter in der Familienphase berührt sie nur am Rand; belastbare Wirkungsstudien fehlen.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=15', null, 'offen', '2026-10-21', false, true, 'blind'),
  (10440, 28, 16, 'ST', 'Kinder und Jugendliche früh für alltägliche Aufgaben sensibilisieren, damit Sorgearbeit besser verteilt wird.', '{2803}', 10384, 1, 3, null, 'Setzt früh an Rollenbildern an und ist mit Lehrplänen und Fortbildung umsetzbar. Ob solche Programme die Erwartungen an Mütter oder die spätere Aufteilung im Haushalt ändern, ist kaum untersucht; Wirkung langfristig und unsicher.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=22', null, 'offen', '2026-10-21', false, true, 'blind'),
  (10441, 28, 17, null, 'Kinderbetreuungs- und Pflegezeiten in der Arbeitslosenversicherung anerkennen, Versicherungsfrist verlängern', '{2802}', null, 1, 2, null, 'Sichert nach Erziehungs- oder Pflegephasen den Zugang zu Arbeitslosengeld und Vermittlung und erleichtert so den Wiedereinstieg etwas; an der Dauer-Teilzeit ändert es wenig, Mehrkosten in der Versicherung.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=22', null, 'offen', '2026-10-21', false, true, 'blind'),
  (10442, 28, 17, null, 'Flexible Arbeitszeitmodelle, um die Verwaltungen als Arbeitgeber attraktiver zu machen', '{2802}', 10380, 1, 3, null, 'Mehr Flexibilität kann Vereinbarkeit und höhere Stundenzahl erleichtern. Ohne Rückkehr- oder Aufstockungsrecht bleibt offen, ob Mütter dadurch aus der Teilzeit kommen; längere Tage können Sorgearbeit auch erschweren.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=16', null, 'offen', '2026-10-21', false, true, 'blind');

select setval(pg_get_serial_sequence('public.massnahmen', 'id'), (select max(id) from public.massnahmen));

