insert into public.instrumente (id, thema_id, name, begruendung, evidenz, beleg_studie_url, ebene, entspricht, ki_entwurf, entwurf_herkunft) values
  (10377, 28, 'Elterngeld-Mindest- und Höchstbetrag anheben (Bund)', 'Geld ist ein Hauptgrund für kurze Elternzeit der Väter, ein höherer Höchstbetrag senkt diese Hürde etwas. Der Mindestbetrag geht aber vor allem an Mütter ohne Vorerwerb und ändert die Aufteilung kaum; Mehrkosten im Haushalt.', 'gemischt', 'https://www.diw.de/de/diw_01.c.673478.de/elterngeld_und_elterngeld_plus_gleichmaessige_aufteilung_zwischen_muettern_und_vaetern_nach_wie_vor_in_weiter_ferne.html', 'bund', null, true, 'blind'),
  (10378, 28, 'Bezahlte Freistellung des zweiten Elternteils direkt nach der Geburt (Bund)', 'Väterzeit nach der Geburt stärkt frühe Beteiligung und entspricht EU-Vorgaben; Studien finden aber nur bei längeren Freistellungen dauerhafte Effekte, bei Hausarbeit verblassen sie. Umlagefinanzierung per Bundesgesetz machbar.', 'gemischt', 'https://childcarecanada.org/node/15425', 'bund', null, true, 'blind'),
  (10379, 28, 'Rechte auf Rückkehr oder Aufstockung von Teilzeit in Vollzeit ausweiten (Bund)', 'Setzt direkt an der ungewollten Dauer-Teilzeit nach der Familienphase an; die bisherige Brückenteilzeit gilt nur in größeren Betrieben. Wirkung kaum evaluiert, Widerstand der Arbeitgeber und Ausnahmen für Kleinbetriebe absehbar.', 'offen', null, 'bund', null, true, 'blind'),
  (10380, 28, 'Flexiblere Arbeitszeitmodelle ermöglichen (Bund)', 'Mehr Flexibilität kann Vereinbarkeit und höhere Stundenzahl erleichtern. Ohne Rückkehr- oder Aufstockungsrecht bleibt offen, ob Mütter dadurch aus der Teilzeit kommen; längere Tage können Sorgearbeit auch erschweren.', 'offen', null, 'bund', null, true, 'blind'),
  (10381, 28, 'Ehegattensplitting durch Individualbesteuerung mit übertragbarem Grundfreibetrag ersetzen (Bund)', 'Das Splitting gilt als Erwerbshemmnis für Zweitverdienerinnen. Simulationen zeigen deutliche Effekte vor allem bei reiner Individualbesteuerung, mit übertragbarem Grundfreibetrag fallen sie kleiner aus; Übergang und Vertrauensschutz aufwendig.', 'gemischt', 'https://www.diw.de/de/diw_01.c.763052.de/s_6900.html', 'bund', null, true, 'blind'),
  (10382, 28, 'Betreuungsgeld für häusliche Betreuung von Kindern unter drei Jahren (Bund)', 'Erweitert die Wahl, senkt laut Studien aber die Erwerbsbeteiligung von Müttern und verfestigt damit Teilzeit und Rollenteilung. Das Bundesverfassungsgericht hat das Bundes-Betreuungsgeld 2015 mangels Bundeszuständigkeit gekippt.', 'belegt', 'https://www.wirtschaftsdienst.eu/inhalt/jahr/2023/heft/5/beitrag/betreuungsgeld-familienpolitische-leistung-oder-hindernis-bei-der-arbeitsmarktintegration.html', 'bund', null, true, 'blind'),
  (10383, 28, 'Antidiskriminierungsstelle und Beratungsstellen für Betroffene stärken (Bund)', 'Mehr Beratung erleichtert Betroffenen von Belästigung den Weg zu Hilfe und macht Rechte bekannter. Betriebliche Beschwerdestellen und Pflichten der Arbeitgeber ändert das nicht direkt; Wirkung kaum untersucht.', 'offen', null, 'bund', null, true, 'blind'),
  (10384, 28, 'Gleichberechtigung und Geschlechterstereotype in Kita und Schule thematisieren (Land)', 'Setzt früh an Rollenbildern an und ist mit Lehrplänen und Fortbildung umsetzbar. Ob solche Programme die Erwartungen an Mütter oder die spätere Aufteilung im Haushalt ändern, ist kaum untersucht; Wirkung langfristig und unsicher.', 'offen', null, 'land', null, true, 'blind'),
  (10385, 28, 'Berufsorientierung ohne Geschlechterklischees an Schulen (Land)', 'Kann Berufswahl und Rollenbilder etwas öffnen und ist schulrechtlich leicht umsetzbar. Die Erwartungen an Mütter in der Familienphase berührt sie nur am Rand; belastbare Wirkungsstudien fehlen.', 'offen', null, 'land', null, true, 'blind'),
  (10386, 28, 'Mädchen für MINT gewinnen und weibliche Vorbilder sichtbar machen (Land)', 'Ein Feldexperiment zeigt, dass Besuche weiblicher Vorbilder Stereotype abbauen und MINT-Studienwahl leicht erhöhen. An Erwartungen an Mütter und Familienrollen setzt das nur am Rand an.', 'belegt', 'https://www.iza.org/de/publications/dp/13163', 'land', null, true, 'blind'),
  (10387, 28, 'Geschlechtersensible Bildungs- und Jugendarbeit fördern (Bund)', 'Kann Rollenbilder früh hinterfragen; der Bund kann über Förderprogramme beitragen, Schule und Kita regeln aber die Länder. Wirkung auf spätere Rollenteilung kaum untersucht.', 'offen', null, 'bund', null, true, 'blind')
