  (28, 12, null, 'massnahmen', null, '2026-10-21', true, '{2801,2802,2803,2804}'),
  (28, 12, 'BE', 'keine', 'Kapitel Frühkindliche Bildung, Kinder und Jugend, Familie (S. 37–38) und Zusammenleben, Familie und Gleichstellung (S. 46–48) sowie Fundstellen S. 8 und 11 gelesen; nichts zu Rollenbildern oder Erwartungen an Mütter.', '2026-10-21', true, '{2803}'),
