  (28, 17, 'BE', 'keine', 'Kapitel „Arbeit und Soziales, Familie“ (S. 10–13) und Fundstellen S. 32, 40, 42 gelesen; nichts zu Rollenbildern oder Erwartungen an Mütter, nichts zu Anerkennung häuslicher Sorgearbeit.', '2026-10-21', true, '{2803}'),
  (28, 17, 'MV', 'keine', 'Kapitel ''Familien im Land stärken'' und ''Kinder und Jugendliche'' (S. 11–14), ''Gute Arbeit'' (S. 19), ''Pflege'' (S. 65–66) und ''Schutz von Frauen'' (S. 71) gelesen; nichts zu Rollenbildern oder Erwartungen an Mütter.', '2026-10-21', true, '{2803}'),
